function pyPerson(id){var R=PY.run,x=R.rows.filter(function(r){return r.employee_id===id})[0];if(!x)return;var it=PY.bs.items,ed=R.canEdit;
  var grp=function(kind,title){var ls=x.lines.filter(function(l){return l.kind===kind}),tot=ls.reduce(function(s,l){return s+l.amount},0);
    return '<div class="py-dg"><h4>'+title+'</h4>'+(ls.length?ls.map(function(l){return '<div class="py-dl"><div><b>'+esc(l.name)+'</b><small>'+esc(l.note||'')+(l.note?' · ':'')+PYSRC[l.src]+'</small></div><span class="num">'+m2(l.amount)+(l.raw!=null?'<small class="py-raw">ก่อนปัด '+m2(l.raw)+'</small>':'')+'</span></div>'}).join(''):'<div class="faint">—</div>')+'<div class="py-dl tot"><b>รวม'+title+'</b><span class="num">'+m2(tot)+'</span></div></div>'};
  var form='';
  if(ed){var cur=x.inputs||{},rec={};x.lines.forEach(function(l){if(l.src==='fixed')rec[l.code]=l.amount});
    var fld=function(i){var v=cur[i.code]?cur[i.code].amount:'';return '<label class="f"><span>'+esc(i.name)+(i.source==='fixed'?' <small class="faint">ประจำ</small>':'')+'</span><input data-pin="'+i.code+'" inputmode="decimal" value="'+(v===''?'':v)+'" placeholder="'+(rec[i.code]?m2(rec[i.code])+' (ประจำ)':'0.00')+'"></label>'};
    var ins=it.filter(function(i){return i.active&&i.source!=='auto'});
    form='<div class="dfs"><h4><span class="n">✎</span>แก้รายการในงวดนี้</h4><p class="faint" style="margin:0 0 8px;font-size:12.5px">ช่องว่าง = ใช้รายการประจำ (ถ้ามี) · ใส่ 0 = ไม่จ่าย/ไม่หักงวดนี้ · ประกันสังคม หัก ณ ที่จ่าย กองทุน และหนี้สิน ระบบคำนวณเอง</p>'+
      '<div class="dfg"><label class="f"><span>วันขาดงาน</span><input data-pin="_absent_days" inputmode="decimal" value="'+(cur._absent_days?cur._absent_days.amount:'')+'" placeholder="'+(x.absent||0)+' (จากระบบลงเวลา)"></label></div>'+
      '<h5 class="py-h5">รายรับ</h5><div class="dfg">'+ins.filter(function(i){return i.kind==='inc'}).map(fld).join('')+'</div><h5 class="py-h5">รายจ่าย</h5><div class="dfg">'+ins.filter(function(i){return i.kind==='ded'}).map(fld).join('')+'</div>'+
      '<label class="f" id="w-reason" style="margin-top:10px"><span>หมายเหตุ (ไม่บังคับ)</span><input id="py-reason" placeholder="เช่น ค่าคอม ต.ค. ตามรายงานฝ่ายขาย"></label></div>'}
  drawer(x.name+' · '+x.code,'<div class="muted" style="margin:-4px 0 12px;font-size:13px">'+esc(x.dept||'—')+' · '+esc(PY.bs.types[x.type]||'')+' · งวด '+esc(ymTh(R.run.ym))+' ('+dTh(R.run.from)+' – '+dTh(R.run.to)+')<br>บัญชี: '+esc(x.bank_name||'—')+' '+esc(x.bank_masked||'')+'</div>'+
    (x.warn.length?'<div class="note-w" style="margin-bottom:12px">'+x.warn.map(esc).join(' · ')+'</div>':'')+grp('inc','รายได้')+grp('ded','รายการหัก')+
    '<div class="py-net"><span>รับสุทธิ (โอน)'+(x.rnd?'<small class="py-raw">ก่อนปัด '+m2(x.net-x.rnd)+' · ปัดเศษ '+pyRnd(x.rnd)+'</small>':'')+'</span><b class="num">'+m2(x.net)+'</b></div>'+form,
    (R.run.status==='closed'||R.run.status==='paid'?'<button class="btn" id="pslip">สลิปเงินเดือน (PDF)</button><span class="sp"></span>':'')+(ed?'<button class="btn" id="px">ปิด</button><button class="btn pri" id="pok">บันทึก + คำนวณใหม่</button>':'<button class="btn" id="px">ปิด</button>'));
  if($('#pslip'))$('#pslip').onclick=function(){pySlips(R,[x],'สลิปเงินเดือน '+x.code+' '+ymTh(R.run.ym))};
  $('.drw').classList.add('wide');$('#px').onclick=closeD;
  if(ed)$('#pok').onclick=function(){var b=this,am={},rs=$('#py-reason').value.trim(),ab;$$('[data-pin]').forEach(function(i){var k=i.dataset.pin,v=i.value.replace(/,/g,'').trim(),o=k==='_absent_days'?(x.inputs._absent_days||{}).amount:(x.inputs[k]||{}).amount;if(String(v)!==String(o===undefined?'':o))(k==='_absent_days'?(ab=v):(am[k]=v))});
    if(!Object.keys(am).length&&ab===undefined)return toast('ไม่มีอะไรเปลี่ยน');if(!rs){$('#w-reason').classList.add('bad');return}
    var d={amounts:am,reason:rs};if(ab!==undefined)d.absent_days=ab;busy(b,1);
    aCall('paySaveInputs',R.run.id,id,d).then(function(r){if(!r.ok){busy(b,0);var k=Object.keys(r.errors||{})[0];if(k==='reason')$('#w-reason').classList.add('bad');var el=$('[data-pin="'+k+'"]');if(el){el.closest('.f').classList.add('bad')}toast((r.errors||{})[k]||'ตรวจข้อมูล',1);return}
      closeD();toast('บันทึกแล้ว · คำนวณใหม่');pyRefreshRun()}).catch(function(e){busy(b,0);toast(e.message,1)})}}

