  var all=PY.prof.slice().sort(function(a,b){return a.code<b.code?-1:1}),rows=all.filter(function(p){return (!q||(p.code+' '+p.name+' '+p.nickname+' '+p.dept+' '+(p.position||'')).toLowerCase().indexOf(q)>=0)&&ofOk('ps',p.dept,p.team)&&pyCoOk(p.co)&&(!PSL.none||!p.base_salary)});
