function bahtTxt(n){n=Math.round((+n||0)*100)/100;var neg=n<0;n=Math.abs(n);var D=['','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'],P=['','สิบ','ร้อย','พัน','หมื่น','แสน'];
  var rd=function(x){var s='',t=String(x),L=t.length;for(var i=0;i<L;i++){var d=+t[i],pos=L-i-1;if(!d)continue;if(pos===1&&d===1)s+='สิบ';else if(pos===1&&d===2)s+='ยี่สิบ';else if(pos===0&&d===1&&L>1)s+='เอ็ด';else s+=D[d]+P[pos]}return s};
  var big=function(x){if(x===0)return 'ศูนย์';var s='',parts=[];while(x>0){parts.unshift(x%1000000);x=Math.floor(x/1000000)}parts.forEach(function(v,i){s+=rd(v)+(i<parts.length-1?'ล้าน':'')});return s};
  var b=Math.floor(n),st=Math.round((n-b)*100);return (neg?'ลบ':'')+big(b)+'บาท'+(st?rd(st)+'สตางค์':'ถ้วน')}
